import{_ as e,o as n,c as a,a3 as o}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Central Application Settings — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Central Application Settings — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/central-settings"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Central Application Settings — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/central-settings"}]]},"headers":[],"relativePath":"user-guide/central-settings.md","filePath":"user-guide/central-settings.md","lastUpdated":1787448410000}'),r={name:"user-guide/central-settings.md"};function i(s,t,d,l,c,g){return n(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="central-application-settings-—-user-guide" tabindex="-1">Central Application Settings — User Guide <a class="header-anchor" href="#central-application-settings-—-user-guide" aria-label="Permalink to &quot;Central Application Settings — User Guide&quot;">​</a></h1><p>Central admins configure platform identity and behavior under <strong>Settings</strong> (not Billing).</p><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>What to set</th></tr></thead><tbody><tr><td><strong>General</strong></td><td><strong>Application Name</strong> — browser title, sidebar, auth screens. <strong>Company Name</strong> — copyrights and email salutations only. Timezone / Locale / Currency (searchable). Registration and Founding Beta access settings.</td></tr><tr><td><strong>Localization</strong></td><td>Date format + 12/24-hour time. Tables and timelines across Central use these formats.</td></tr><tr><td><strong>Mail</strong></td><td>Provider (SMTP, Postmark, Mailgun, Log, …), provider credentials, From / Reply-To / timeout. For Postmark/Mailgun: copy the <strong>Webhook URL</strong>, set the signing secret, and select which delivery events to process. Use <strong>Send test</strong> (can use unsaved form values). Leave secrets blank to keep existing values.</td></tr><tr><td><strong>Branding</strong></td><td>Button color (primary buttons), support email (shown on maintenance/registration-closed and tenant emails), logo + favicon uploads with preview. Until you upload a logo/favicon, the SPA uses the EloSync press-kit App Store light icon (<code>/brand/elosync-app-icon-light.png</code>) for the shell, tab icon, and (via <code>FRONTEND_URL</code>) default web push / non-Branded email chrome.</td></tr><tr><td><strong>Security</strong></td><td>Session timeout (minutes), minimum password length, require special character. Applies to Central and Tenant password forms.</td></tr><tr><td><strong>Maintenance</strong></td><td>Tenant Application only. Central stays fully usable so you can turn maintenance off. Optional message + ETA.</td></tr><tr><td><strong>Billing</strong></td><td>Invoice prefix, proration mode, default gateway code, trial / Stripe flags. Gateway secrets are managed under <strong>Billing → Payment Gateways</strong>.</td></tr><tr><td><strong>AI</strong></td><td>Platform master switch, allow Platform / BYOK, provider (OpenAI or Anthropic), API key, and <strong>Default / Fast / Advanced</strong> models (dropdowns filtered by provider). Credit knobs and <strong>Test AI connection</strong>.</td></tr></tbody></table><h2 id="registration-closed" tabindex="-1">Registration closed <a class="header-anchor" href="#registration-closed" aria-label="Permalink to &quot;Registration closed&quot;">​</a></h2><p>When <strong>Registration enabled</strong> is off:</p><ol><li>Ordinary <code>POST /public/register-workspace</code> requests return <code>403</code>; a valid accepted Founding Beta invite token can still register.</li><li>Visiting <code>/register</code> shows the dedicated <strong>Registration closed</strong> page (with logo/support/copyright when configured).</li></ol><p>General settings control its call to action:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Founding Beta enabled</strong> (<code>founding_beta_enabled</code>)</td><td>Shows the beta application CTA while registration is closed.</td></tr><tr><td><strong>Founding Beta apply URL</strong> (<code>founding_beta_apply_url</code>)</td><td>Sets the CTA destination, normally <code>https://elosync.com/beta/</code>.</td></tr><tr><td><strong>Founding Beta invite lifetime</strong> (<code>founding_beta_invite_ttl_days</code>)</td><td>Sets how many days each new or resent workspace invite remains valid (<strong>1–90</strong>).</td></tr></tbody></table><p>Turn off <strong>Founding Beta enabled</strong> to hide the CTA without opening public registration. Enabling ordinary registration is a separate launch decision.</p><h2 id="tenant-maintenance" tabindex="-1">Tenant maintenance <a class="header-anchor" href="#tenant-maintenance" aria-label="Permalink to &quot;Tenant maintenance&quot;">​</a></h2><p>When <strong>Tenant maintenance mode</strong> is on:</p><ul><li>Tenant API responses return <code>503</code> with <code>code: maintenance_mode</code>.</li><li>Tenant SPA shows the branded maintenance page.</li><li>Central admin API and UI continue to work.</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Change Application Name if you want the product title to update immediately (after save + public bootstrap refresh).</li><li>Use Company Name for legal/copyright wording without renaming the product in the chrome.</li><li>After mail provider changes, always send a test email before relying on invites or password resets. Restart queue workers after credential changes so queued mail picks up the new config.</li><li>For Postmark/Mailgun, paste the webhook URL into the provider dashboard and enable the same events selected in Settings. Open/Click also require open tracking and link tracking in the provider console — saving Central settings does not change Postmark/Mailgun checkboxes.</li><li>Review delivery history under <strong>Email logs</strong> — status progresses through delivered → opened → clicked when those webhooks arrive; open a row for open/click counts, full message body, and <strong>Resend</strong> when you have <code>email-logs.resend</code>.</li></ul>',15)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
